def fixture():
    css='\n'.join((STATIC/name).read_text() for name in ['tf-portal.css','work-report.css','responsive.css'])
    setup="""window.I18n={t:s=>s};Object.defineProperty(navigator,'onLine',{get:()=>false});let requests=[],fail=true,saved=0,stored=[],deferRead=false,pendingRead;window.confirm=()=>true;window.fetch=async(url,options={})=>{requests.push([url,options]);if(fail)throw Error('offline');if(!options.method){if(deferRead){const snapshot=structuredClone(stored);return new Promise(resolve=>{pendingRead=()=>resolve({ok:true,json:async()=>({owner_id:1,items:snapshot})});});}return {ok:true,json:async()=>({owner_id:1,items:stored})};}const body=JSON.parse(options.body),row={id:1,from_code:body.waypoints[0],to_code:body.waypoints.at(-1),valid_until:body.valid_until,waypoints:body.waypoints,routes:body.routes,revision:(options.method==='PUT'?'b':'a').repeat(64)};stored=[row];return {ok:true,json:async()=>({owner_id:1,items:[],saved_routes:stored})};};"""
    checks=r'''
(async()=>{
 const assert=(v,m)=>{if(!v)throw Error(m);},wait=(ms=25)=>new Promise(r=>setTimeout(r,ms));
 const originalLoad=M1Map.load;let release;M1Map.load=()=>new Promise(resolve=>{release=()=>originalLoad().then(resolve);});const root=document.getElementById('root'),editor=ManualRouteEditor.mount({id:1},root,async()=>{saved++;});assert(root.querySelector('[data-route-start]').disabled,'Start selection waits for reference geometry');release();await wait();M1Map.load=originalLoad;
 assert(root.querySelector('[data-m1-country=DEU]'),'Local Germany background before any selection');
 const input=root.querySelector('[data-route-start]');input.focus();input.value='AFW';input.dispatchEvent(new Event('input',{bubbles:true}));await wait(250);
 const option=[...document.querySelectorAll('.station-picker button')].find(button=>button.textContent.startsWith('AFW ·'));assert(option,'DS100 start found');option.click();
 assert(editor.waypoints.join(',')==='AFW','Chosen station starts the route');const mapUndo=root.querySelector('[data-route-map-undo]');assert(mapUndo&&!mapUndo.disabled&&mapUndo.getAttribute('aria-label')==='Rückgängig','Accessible undo icon directly on the map');mapUndo.click();assert(editor.waypoints.length===0&&mapUndo.disabled,'Map undo removes first point and then disables itself');editor.select(M1Map.points().byCode.get('AFW')[0],true);
 const origin=root.querySelector('[data-m1-point=AFW]');assert(origin&&origin.getAttribute('transform').includes('300'),'Autozoom centres the chosen station');assert(root.querySelector('[data-m1-point=AFR]'),'Connected operating points visible after autozoom');
 root.querySelector('[data-m1-point=AFR]').dispatchEvent(new MouseEvent('click',{bubbles:true}));
 assert(editor.waypoints.join(',')==='AFW,AFR','Map click appends the next station');
 const choose=root.querySelector('[data-route-waypoint] select');if(!choose.value){choose.value='1000';choose.dispatchEvent(new Event('change'));}
 const line=root.querySelector('[data-manual-route-line]');assert(line&&line.getAttribute('stroke')==='#7cfc00'&&!line.hasAttribute('stroke-dasharray'),'Preview follows M1 as continuous light-green line');
 assert(requests.filter(([,o])=>o.method).length===0&&saved===0,'Selection has not been uploaded or saved');
 const date=root.querySelector('[data-route-until]');assert(date.max&&date.value===date.max,'One calendar year upper bound');
 const form=root.querySelector('form');await form.onsubmit({preventDefault(){}});assert(editor.waypoints.length===2&&!root.querySelector('[data-route-save]').disabled,'Failed save keeps route and permits retry');
 fail=false;await form.onsubmit({preventDefault(){}});assert(saved===1&&editor.waypoints.length===0,'Explicit successful save clears only the selection');const payload=JSON.parse(requests.at(-1)[1].body);assert(payload.routes[0]==='1000'&&payload.waypoints.join(',')==='AFW,AFR','Confirmed M1 route sent without GPS points');assert(!('points' in payload),'No fabricated GPS');const savedRow=root.querySelector('[data-saved-route]');assert(savedRow&&savedRow.cells[0].textContent==='AFW'&&savedRow.cells[1].textContent==='AFR','Saved list contains route endpoints');assert(/^\d{2}\.\d{2}\.\d{4}$/.test(savedRow.cells[2].textContent),'Saved validity in German format');savedRow.click();assert(editor.waypoints.join(',')==='AFW,AFR'&&root.querySelector('[data-manual-route-line]'),'Saved row restores complete route to map');assert(root.querySelectorAll('[data-route-waypoint]').length===2&&root.querySelector('[data-route-waypoint=AFW]').textContent.includes('172,9'),'Selection table restores DS100, station and M1 mileage');assert(root.querySelector('[data-route-save]').textContent==='Änderungen speichern','Loaded record saves changes instead of creating a duplicate');date.value=date.min;date.dispatchEvent(new Event('change'));await form.onsubmit({preventDefault(){}});assert(requests.at(-1)[1].method==='PUT'&&JSON.parse(requests.at(-1)[1].body).expected_sha256==='a'.repeat(64),'Editing carries original revision');assert(root.querySelectorAll('[data-saved-route]').length===1&&root.querySelectorAll('[data-route-waypoint]').length===0&&editor.waypoints.length===0,'Edit updates saved list and clears selection table');assert(saved===2,'Both explicit confirmations completed');
 for(const control of root.querySelectorAll('input,button,select')){const box=control.getBoundingClientRect();assert(box.left>=0&&box.right<=innerWidth+1,'Controls fit viewport');}
 const tabs=document.createElement('div');tabs.innerHTML='<button id="routeTab-view">View</button><button id="routeTab-create">Create</button><section id="routePanel-view"><div id="routeKnowledgeWorkspace"></div></section><section id="routePanel-create" hidden><div id="manualRouteWorkspace"></div></section>';document.body.append(tabs);let publishInventory;const refs=['BSPD','BAS','BSFD','BFKS','BFIN','BAFI'].map(code=>M1Map.points().byCode.get(code).find(p=>p.route==='6100'));window.GpsRecorder={localRecords:async()=>[{journey_id:'own-gps',points:refs.map((p,i)=>({...p,t:Date.now()-60000+i*5000,accuracy:5}))}]};window.RouteCsv={mount:(user,host,onData)=>{publishInventory=onData;return Promise.resolve();}};await startRouteKnowledge({id:1},{fetch:async()=>({ok:true,json:async()=>({owner_id:1,items:[],next_offset:null})})});assert(!document.getElementById('routePanel-view').hidden&&document.getElementById('routePanel-create').hidden,'Display is the default subtab');document.getElementById('routeTab-create').click();assert(document.getElementById('routePanel-view').hidden&&!document.getElementById('routePanel-create').hidden&&document.getElementById('manualRouteWorkspace').querySelector('[data-route-start]'),'Create subtab opens its own map editor');await wait();const editorRoot=document.getElementById('manualRouteWorkspace'),start=editorRoot.querySelector('[data-route-start]');start.focus();start.value='BSPD';start.dispatchEvent(new Event('input',{bubbles:true}));await wait(250);[...document.querySelectorAll('.station-picker button')].find(b=>b.textContent.startsWith('BSPD ·')).click();[...editorRoot.querySelectorAll('.gps-map-tools button')].find(b=>b.textContent==='−').click();const match=M1Map.candidates('BSPD','BAFI',RailNetworkSeed).find(m=>m.route==='6100');assert(match,'Real M1 reference for existing inventory');const imported={section:'Existing import',route_number:'6100',from_code:'BSPD',to_code:'BAFI',status:'streckenkundig',valid_until:editorRoot.querySelector('[data-route-until]').max,map_match:match};publishInventory({items:[imported]});let inventory=editorRoot.querySelector('[data-route-existing-knowledge]');assert(inventory.querySelector('[data-imported-knowledge=qualified]'),'Confirmed imported knowledge visible in editor');assert(inventory.querySelector('[data-route-track]'),'Own measured GPS knowledge visible in editor');const fixedCentre=editorRoot.querySelector('[data-m1-point=BSPD]').getAttribute('transform');for(const code of ['BAS','BSFD','BFKS','BFIN','BAFI']){const point=editorRoot.querySelector('[data-m1-point='+code+']');assert(point,'Next operating point remains visible: '+code);point.dispatchEvent(new MouseEvent('click',{bubbles:true}));for(const select of editorRoot.querySelectorAll('[data-route-waypoint] select'))if(!select.value){select.value='6100';select.dispatchEvent(new Event('change'));}}assert(editorRoot.querySelectorAll('[data-route-waypoint]').length===6,'Six distinct stations appended in sequence');assert(editorRoot.querySelector('[data-m1-point=BSPD]').getAttribute('transform')===fixedCentre,'Viewport does not jump after each station click');inventory=editorRoot.querySelector('[data-route-existing-knowledge]');const preview=editorRoot.querySelector('[data-manual-route-line]');assert(preview&&!!(inventory.compareDocumentPosition(preview)&Node.DOCUMENT_POSITION_FOLLOWING),'New route is above all existing knowledge');assert(preview.getAttribute('pointer-events')==='none','Preview never intercepts further station clicks');publishInventory({items:[imported,{...imported,manual:true,id:'manual-1'}]});assert(editorRoot.querySelectorAll('[data-route-waypoint]').length===6,'Late inventory refresh preserves the drawn route');const maskIds=[...document.querySelectorAll('mask[id]')].map(mask=>mask.id);assert(maskIds.length>1&&new Set(maskIds).size===maskIds.length,'Independent SVG maps have unique priority masks');const labels=editorRoot.querySelectorAll('[data-rail-route-label]');assert(labels.length>0,'Route numbers appear at detail zoom');for(const label of labels){assert(RailNetwork.visible(label.getAttribute('data-rail-route-label')),'S-Bahn route numbers excluded');assert(label.querySelector('text').getAttribute('fill')==='#ff0000'&&label.querySelector('text').getAttribute('stroke')==='#000','Route number red with black outline');}const directUndo=editorRoot.querySelector('[data-route-map-undo]');directUndo.click();directUndo.click();assert(editorRoot.querySelectorAll('[data-route-waypoint]').length===4,'Every map undo click removes exactly one step');assert(editorRoot.querySelector('[data-manual-route-line]')&&editorRoot.querySelector('[data-imported-knowledge]'),'Undo keeps the remaining preview and existing knowledge');document.getElementById('routeTab-view').click();assert(!document.getElementById('routePanel-view').hidden,'Return to display subtab');
 stored=[];deferRead=true;const raceRoot=document.createElement('div');document.body.append(raceRoot);const raceEditor=ManualRouteEditor.mount({id:1},raceRoot,async()=>{});await wait();raceEditor.select(M1Map.points().byCode.get('AFW')[0],true);raceEditor.select(M1Map.points().byCode.get('AFR')[0]);await raceRoot.querySelector('form').onsubmit({preventDefault(){}});assert(raceRoot.querySelectorAll('[data-saved-route]').length===1,'Newly saved route visible while old list request is pending');pendingRead();await wait();deferRead=false;assert(raceRoot.querySelectorAll('[data-saved-route]').length===1&&raceRoot.querySelectorAll('[data-route-waypoint]').length===0,'Late old list cannot remove a newly saved route or repopulate selection');
 window.parent.postMessage({layoutStatus:'pass'},'*');
})().catch(error=>window.parent.postMessage({layoutStatus:'fail',message:error.stack},'*'));
'''
    return '<!doctype html><html><head><meta charset="utf-8"><style>'+css+'</style></head><body><main id="root"></main><script>'+setup+'</script>'+''.join('<script src="/tf/'+name+'"></script>' for name in ASSETS)+'<script>'+checks+'</script></body></html>'
if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--output-dir',required=True);args=parser.parse_args()
    check_pages(fixture,args.output_dir,widths=(1280,800,375,320),assets={'/tf/'+name:STATIC/name for name in ASSETS},label='Manual M1 route',timeout=30)
